module TopModule (
  input [5:0] y,
  input w,
  output Y1,
  output Y3
);
assign Y1 = w;
  assign Y3 = y[3];
  always @(y or w) begin
    case (y)
      6'b000000: begin
        y <= 6'b000001;
      end
      6'b000001: begin
        y <= 6'b000010;
      end
      6'b000010: begin
        y <= 6'b000100;
      end
      6'b000100: begin
        y <= 6'b001000;
      end
      6'b001000: begin
        y <= 6'b010000;
      end
      6'b010000: begin
        y <= 6'b100000;
      end
      default: begin
        y <= 6'b000000;
      end
    endcase
  end
endmodule

module TopModule (
  input  [99:0] in,
  output [99:0] out_both,
  output [99:0] out_any,
  output [99:0] out_different
);
assign out_both[99] = 0;
  assign out_any[99] = 0;
  assign out_different[99] = 0;
  genvar i;
  generate for (i = 0; i < 100; i = i + 1) begin: gen
    assign out_both[i] = in[i] & in[i - 1];
    assign out_any[i] = in[i] | in[i + 1];
    assign out_different[i] = in[i] != in[i - 1];
  end
  endgenerate
endmodule

