module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);
reg [3:0] state;
  reg start_shifting_reg;
  reg [3:0] next_state;
  always @(posedge clk) begin
    if (reset) begin
      state <= 4'b0000;
      start_shifting_reg <= 0;
    end else begin
      state <= next_state;
      start_shifting_reg <= start_shifting;
    end
  end
  always @(*) begin
    case (state)
      4'b0000: begin
        if (data) begin
          next_state <= 4'b0001;
        end else begin
          next_state <= 4'b0000;
        end
      end
      4'b0001: begin
        if (data) begin
          next_state <= 4'b0010;
        end else begin
          next_state <= 4'b0001;
        end
      end
      4'b0010: begin
        if (data) begin
          next_state <= 4'b0100;
        end else begin
          next_state <= 4'b0010;
        end
      end
      4'b0100: begin
        if (data) begin
          next_state <= 4'b1000;
        end else begin
          next_state <= 4'b0100;
        end
      end
      4'b1000: begin
        if (data) begin
          next_state <= 4'b1001;
        end else begin
          next_state <= 4'b1000;
        end
      end
      4'b1001: begin
        if (data) begin
          next_state <= 4'b1010;
        end else begin
          next_state <= 4'b1001;
        end
      end
      4'b1010: begin
        if (data) begin
          next_state <= 4'b1100;
        end else begin
          next_state <= 4'b1010;
        end
      end
      4'b1100: begin
        if (data) begin
          next_state <= 4'b1101;
        end else begin
          next_state <= 4'b1100;
        end
      end
      4'b1101: begin
        next_state <= 4'b1101;
        start_shifting_reg <= 1;
      end
      default: begin
        next_state <= 4'b0000;
      end
    endcase
  end
  assign start_shifting = start_shifting_reg;
endmodule

