      q[0] <= neighbors[0][0] ^ neighbors[0][1];
      for (int i = 1; i < 511; i = i + 1) begin
        q[i] <= neighbors[i][0] ^ neighbors[i][1];
      end
      q[511] <= neighbors[511][0] ^ neighbors[511][1];
    end
  end
  always @(posedge clk) begin
    neighbors[0][0] <= q[0];
    neighbors[0][1] <= q[1];
    for (int i = 1; i < 511; i = i + 1) begin
      neighbors[i][0] <= q[i];
      neighbors[i][1] <= q[i + 1];
    end
    neighbors[511][0] <= q[511];
    neighbors[511][1] <= q[512];
  end
endmodule

