  reg walk_right;
  reg [1:0] state;
  always @(posedge clk) begin
    if (arreset) begin
      walk_left <= 1'b0;
      walk_right <= 1'b0;
      state <= 2'b00;
    end else begin
      case (state)
        2'b00: begin
          if (bump_left) begin
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            state <= 2'b01;
          end else if (bump_right) begin
            walk_left <= 1'b0;
            walk_right <= 1'b1;
            state <= 2'b10;
          end else begin
            walk_left <= 1'b0;
            walk_right <= 1'b0;
            state <= 2'b00;
          end
        end
        2'b01: begin
          if (bump_left) begin
            walk_left <= 1'b0;
            walk_right <= 1'b1;
            state <= 2'b10;
          end else if (bump_right) begin
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            state <= 2'b01;
          end else begin
            walk_left <= 1'b0;
            walk_right <= 1'b0;
            state <= 2'b00;
          end
        end
        2'b10: begin
          if (bump_left) begin
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            state <= 2'b01;
          end else if (bump_right) begin
            walk_left <= 1'b0;
            walk_right <= 1'b1;
            state <= 2'b10;
          end else begin
            walk_left <= 1'b0;
            walk_right <= 1'b0;
            state <= 2'b00;
