  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      byte <= 8'b00000000;
      done_reg <= 1'b0;
    end else begin
      if (state == 3'b000) begin
        if (in[3]) begin
          state <= 3'b001;
          byte <= in;
        end
      end else if (state == 3'b001) begin
        if (in[3]) begin
          state <= 3'b010;
          byte <= in;
        end
      end else if (state == 3'b010) begin
        if (in[3]) begin
          state <= 3'b000;
          done_reg <= 1'b1;
        end else begin
          byte <= byte << 1;
          byte[7] <= in[7];
          byte[6] <= in[6];
          byte[5] <= in[5];
          byte[4] <= in[4];
          byte[3] <= in[3];
          byte[2] <= in[2];
          byte[1] <= in[1];
          byte[0] <= in[0];
        end
      end
    end
  end
  assign done = done_reg;
endmodule

