  input w,
  output reg Y1
);
reg [2:0] y_next;

always @ (y or w) begin
  case (y)
    3'b000: begin
      if (w) begin
        y_next <= 3'b001;
      end else begin
        y_next <= 3'b000;
      end
    end
    3'b001: begin
      if (w) begin
        y_next <= 3'b010;
      end else begin
        y_next <= 3'b001;
      end
    end
    3'b010: begin
      if (w) begin
        y_next <= 3'b011;
      end else begin
        y_next <= 3'b010;
      end
    end
    3'b011: begin
      if (w) begin
        y_next <= 3'b100;
      end else begin
        y_next <= 3'b011;
      end
    end
    3'b100: begin
      if (w) begin
        y_next <= 3'b101;
      end else begin
        y_next <= 3'b100;
      end
    end
    3'b101: begin
      if (w) begin
        y_next <= 3'b110;
      end else begin
        y_next <= 3'b101;
      end
    end
    3'b110: begin
      if (w) begin
        y_next <= 3'b111;
      end else begin
        y_next <= 3'b110;
      end
    end
    3'b111: begin
      if (w) begin
        y_next <= 3'b000;
      end else begin
        y_next <= 3'b111;
      end
    end
  endcase
end

