module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
) (
	input  clk, reset_n,
	input         [WIDTH-1:0] t0_data,
	input                     t0_valid,
	output logic              t0_ready,
	output logic  [WIDTH-1:0] i0_data,
	output logic              i0_valid,
	input                     i0_ready
);
logic  [WIDTH-1:0] dat0, dat1;
logic              valid0, valid1;
logic              s, s_next;
logic              t0_ready_next;

assign t0_ready = t0_ready_next;

always_ff @(posedge clk, negedge reset_n) begin
	if (!reset_n) begin
		s <= S0;
	end else begin
		s <= s_next;
	end
end

always_comb begin
	s_next = s;
	t0_ready_next = t0_ready;
	if (s == S0) begin
		s_next = S1;
		t0_ready_next = 1'b0;
	end else if (s == S1) begin
		s_next = S2;
		t0_ready_next = t0_valid;
	end else if (s == S2) begin
		s_next = S3;
		t0_ready_next = 1'b0;
	end else if (s == S3) begin
		s_next = S4;
		t0_ready_next = 1'b0;
	end else if (s == S4) begin
		s_next = S0;
		t0_ready_next = 1'b0;
	end
end

always_comb begin
	if (s == S0) begin
		dat0 = t0_data;
		valid0 = t0_valid;
	end else if (s == S1) begin
		dat0 = dat1;
		valid0 = valid1;
	end else if (s == S2) begin
		dat1 = t0_data;
		valid1 = t0_valid;
	end else if (s == S3) begin
		dat1 = dat0;
		valid1 = valid0;
	end
end

assign i0_data = s == S0 ? dat0 : dat1;
assign i0_valid = s == S0 ? valid0 : valid1;

endmodule

