    if((counter == 2)) begin
      counter <= 0;
    end
    else begin
      counter <= counter + 1;
    end
  end
  assign clk_o = (counter == 1) || (counter == 3) ? 1'b1 : 1'b0;
  assign count_o = counter;
endmodule

