module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0] ZERO = 2'b00;
localparam [1:0] ONE  = 2'b01;
localparam [1:0] TWO  = 2'b10;

reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [1:0]   state_p1;
reg [1:0]   state_p2;

always @(posedge clk) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        state_p1 <= ZERO;
        state_p2 <= ZERO;
    end else begin
        case (state_p1)
            ZERO: begin
                if (s_valid && s_ready) begin
                    data_p1 <= s_data;
                    state_p1 <= ONE;
                end
            end
            ONE: begin
                if (s_valid && s_ready) begin
                    data_p1 <= s_data;
                    state_p1 <= TWO;
                end
            end
            TWO: begin
                if (s_valid && s_ready) begin
                    data_p1 <= s_data;
                    state_p1 <= ZERO;
                end
            end
            default: begin
                data_p1 <= {N{1'b0}};
                state_p1 <= ZERO;
            end
        endcase
        case (state_p2)
            ZERO: begin
                if (m_ready) begin
                    data_p2 <= data_p1;
                    state_p2 <= ONE;
                end
            end
            ONE: begin
                if (m_ready) begin
                    data_p2 <= data_p1;
                    state_p2 <= TWO;
                end
            end
            TWO: begin
                if (m_ready) begin
                    data_p2 <= data_p1;
                    state_p2 <= ZERO;
                end
            end
            default: begin
                data_p2 <= {N{1'b0}};
                state_p2 <= ZERO;
            end
        endcase
    end
end

assign s_ready = state_p1 == ZERO;
assign m_data  = data_p2;
assign m_valid = state_p2 == ZERO;

endmodule

