assign src1_rdy_o = (state == DATA1) && src_rdy_i;
always @(posedge clk) begin
  if (reset) begin
    state <= IDLE;
    data0_o <= 0;
    data1_o <= 0;
    src0_rdy_o <= 0;
    src1_rdy_o <= 0;
    eof <= 0;
  end else if (clear) begin
    state <= IDLE;
    data0_o <= 0;
    data1_o <= 0;
    src0_rdy_o <= 0;
    src1_rdy_o <= 0;
