          state <= DATA1;
          data1_o <= data_i;
          src0_rdy_o <= 0;
          src1_rdy_o <= 1;
          eof <= 0;
        end else begin
          state <= IDLE;
          data0_o <= 0;
          data1_o <= 0;
          src0_rdy_o <= 0;
          src1_rdy_o <= 0;
          eof <= 0;
        end
      end
      DATA0: begin
        if (eof) begin
          state <= IDLE;
          data0_o <= 0;
          src0_rdy_o <= 0;
          src1_rdy_o <= 0;
          eof <= 0;
        end else if (dst1_rdy_i) begin
          state <= DATA1;
          data1_o <= data_i;
          src0_rdy_o <= 0;
          src1_rdy_o <= 1;
          eof <= 0;
        end else begin
          state <= DATA0;
          data0_o <= data_i;
          src0_rdy_o <= 1;
          src1_rdy_o <= 0;
          eof <= 0;
        end
      end
      DATA1: begin
        if (eof) begin
          state <= IDLE;
          data1_o <= 0;
          src0_rdy_o <= 0;
          src1_rdy_o <= 0;
          eof <= 0;
        end else if (dst0_rdy_i) begin
          state <= DATA0;
          data0_o <= data_i;
          src0_rdy_o <= 1;
          src1_rdy_o <= 0;
          eof <= 0;
