          state <= DATA1;
          data1_o <= data_i;
          src0_rdy_o <= 0;
          src1_rdy_o <= 1;
          eof <= 0;
        end
      end
      default: begin
        state <= IDLE;
        data0_o <= 0;
        data1_o <= 0;
        src0_rdy_o <= 0;
        src1_rdy_o <= 0;
        eof <= 0;
