module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW+DW-1:0] addr_req;
reg [AW+DW-1:0] cached_addr0, cached_addr1;
reg [DW-1:0]    cached_data0, cached_data1;
reg              subaddr;
reg              good;

assign addr_req = {addr, {DW{1'b0}}};

always @ (posedge clk or posedge rst)
begin
    if (rst)
    begin
        addr_req <= {AW+DW{1'b0}};
        cached_addr0 <= {AW+DW{1'b0}};
        cached_addr1 <= {AW+DW{1'b0}};
        cached_data0 <= {DW{1'b0}};
        cached_data1 <= {DW{1'b0}};
        subaddr <= 0;
        good <= 0;
    end
    else if (clr)
    begin
        addr_req <= {AW+DW{1'b0}};
        cached_addr0 <= {AW+DW{1'b0}};
        cached_addr1 <= {AW+DW{1'b0}};
        cached_data0 <= {DW{1'b0}};
        cached_data1 <= {DW{1'b0}};
        subaddr <= 0;
        good <= 0;
    end
    else if (addr_ok)
    begin
        addr_req <= addr_req[AW+DW-1:0] + {DW{1'b0}};
        cached_addr0 <= addr_req[AW+DW-1:0];
        cached_addr1 <= addr_req[AW+DW-1:0];
        cached_data0 <= {DW{1'b0}};
        cached_data1 <= {DW{1'b0}};
        subaddr <= addr_req[AW+DW-1:AW];
        good <= 0;
    end
    else
    begin
        addr_req <= addr_req[AW+DW-1:0] + {DW{1'b0}};
        cached_addr0 <= cached_addr0[AW+DW-1:0];
        cached_addr1 <= cached_addr1[AW+DW-1:0];
        cached_data0 <= cached_data0[DW-1:0];
        cached_data1 <= cached_data1[DW-1:0];
        subaddr <= subaddr;
        good <= good;
    end
end

always @ (posedge clk or posedge rst)
begin
    if (rst)
    begin
        req <= 0;
        data_ok <= 0;
        sdram_addr <= {AW+DW{1'b0}};
        dout <= {DW{1'b0}};
    end
    else if (clr)
    begin
        req <= 0;
        data_ok <= 0;
        sdram_addr <= {AW+DW{1'b0}};
        dout <= {DW{1'b0}};
    end
    else if (addr_ok)
    begin
        req <= 0;
        data_ok <= 0;
        sdram_addr <= {AW+DW{1'b0}};
        dout <= {DW{1'b0}};
    end
    else if (we)
    begin
        if (good)
        begin
            cached_data0 <= din;
            cached_data1 <= din;
            data_ok <= 1;
        end
        else
        begin
            data_ok <= 0;
        end
    end
    else if (addr_req[AW+DW-1:AW] == cached_addr0[AW+DW-1:AW])
    begin
        req <= 0;
        data_ok <= 0;
        sdram_addr <= {AW+DW{1'b0}};
        dout <= {DW{1'b0}};
    end
    else if (addr_req[AW+DW-1:AW] == cached_addr1[AW+DW-1:AW])
    begin
        req <= 0;
        data_ok <= 0;
        sdram_addr <= {AW+DW{1'b0}};
        dout <= {DW{1'b0}};
    end
    else
    begin
        req <= 1;
        data_ok <= 0;
        sdram_addr <= addr_req[AW+DW-1:AW] + offset;
        dout <= {DW{1'b0}};
    end
end

always @ (posedge clk or posedge rst)
begin
    if (rst)
    begin
        good <= 0;
    end
    else if (clr)
    begin
        good <= 0;
    end
    else if (addr_ok)
    begin
        good <= 1;
    end
    else if (we)
    begin
        if (addr_req[AW+DW-1:AW] == cached_addr0[AW+DW-1:AW])
        begin
            good <= 0;
        end
        else if (addr_req[AW+DW-1:AW] == cached_addr1[AW+DW-1:AW])
        begin
            good <= 0;
        end
        else
        begin
            good <= 1;
        end
    end
    else
    begin
        good <= good;
    end
end

assign dout = (subaddr == 0) ? cached_data0 : cached_data1;

endmodule

