module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [6:0] nextY;
reg [2:0] nextD;
reg [2:0] nextA;
reg [2:0] nextWR;
reg [2:0] nextRD;
reg [2:0] nextCLK;
reg [2:0] nextRST;
  always @(posedge CLK, posedge RST) begin
    if(RST == 1'b1) begin
      nextD <= 3'b000;
      nextA <= 3'b000;
      nextWR <= 3'b000;
      nextRD <= 3'b000;
      nextCLK <= 3'b000;
      nextRST <= 3'b000;
    end else begin
      nextD <= D;
      nextA <= A;
      nextWR <= WR;
      nextRD <= RD;
      nextCLK <= CLK;
      nextRST <= RST;
    end
  end
  always @(nextD, nextA, nextWR, nextRD, nextCLK, nextRST) begin
    if(nextRD == 3'b000) begin
      if(nextWR == 3'b000) begin
        nextY <= nextD;
      end
    end
    else if(nextRD == 3'b001) begin
      if(nextWR == 3'b000) begin
        nextY <= {nextD[1:0],1'b0};
      end
      else if(nextWR == 3'b001) begin
        nextY <= {nextD[2:1],1'b0};
      end
      else if(nextWR == 3'b010) begin
        nextY <= {nextD[2],1'b0};
      end
      else if(nextWR == 3'b011) begin
        nextY <= {1'b0,1'b0};
      end
      else if(nextWR == 3'b100) begin
        nextY <= {1'b0,nextD[1:0]};
      end
      else if(nextWR == 3'b101) begin
        nextY <= {1'b0,nextD[2:1]};
      end
      else if(nextWR == 3'b110) begin
        nextY <= {1'b0,nextD[2]};
      end
      else if(nextWR == 3'b111) begin
        nextY <= {1'b0,1'b0};
      end
    end
  end
  assign WCTRL = nextWR;
  assign Y = nextY;
endmodule

