reg [10:0] Y;
reg H_SYNC;
reg V_SYNC;
reg DISP_EN;
  always @(posedge CLK, posedge RST) begin
    if(RST == 1'b1) begin
      X <= 0;
      Y <= 0;
      H_SYNC <= 0;
      V_SYNC <= 0;
      DISP_EN <= 0;
    end else begin
      if(X == H_TOTAL - 1) begin
        X <= 0;
        Y <= Y + 1;
      end
      else begin
        X <= X + 1;
      end
      if(Y == V_TOTAL - 1) begin
        Y <= 0;
        H_SYNC <= 0;
        V_SYNC <= 0;
        DISP_EN <= 0;
      end
      else begin
        if(X >= H_ACTIVE) begin
          H_SYNC <= 0;
        end
        else begin
          H_SYNC <= 1;
        end
        if(Y >= V_ACTIVE) begin
          V_SYNC <= 0;
        end
        else begin
          V_SYNC <= 1;
        end
        if(X >= H_ACTIVE && Y >= V_ACTIVE) begin
          DISP_EN <= 0;
        end
        else begin
          DISP_EN <= 1;
        end
      end
    end
  end
endmodule

