module sqrt_pipelined
  #(
    parameter
    INPUT_BITS   = 16, 
    OUTPUT_BITS  = INPUT_BITS / 2 + INPUT_BITS % 2 
    )
  (
   input                        clk,        
   input                        reset_n,    
   input                        start,      
   input [INPUT_BITS-1:0]       radicand,   
   output reg                   data_valid, 
   output reg [OUTPUT_BITS-1:0] root        
   );
reg [OUTPUT_BITS-1:0] root_gen;
reg [OUTPUT_BITS-1:0] radicand_gen;
reg [OUTPUT_BITS-1:0] mask_gen;
reg [OUTPUT_BITS-1:0] start_gen;

always @(posedge clk or negedge reset_n)
begin
  if (!reset_n)
  begin
    start_gen <= 0;
    radicand_gen <= 0;
    root_gen <= 0;
    mask_gen <= 0;
  end
  else
  begin
    start_gen <= start;
    radicand_gen <= radicand;
    root_gen <= root;
    mask_gen <= ~root_gen;
  end
end

genvar i;
generate
  for (i = 0; i < OUTPUT_BITS; i = i + 1)
  begin: stage
    always @(posedge clk or negedge reset_n)
    begin
      if (!reset_n)
      begin
        radicand_gen <= 0;
        root_gen <= 0;
        mask_gen <= 0;
      end
      else
      begin
        if (start_gen)
        begin
          radicand_gen <= radicand_gen - mask_gen;
          root_gen <= root_gen + 1;
        end
      end
    end
  end
endgenerate

always @(posedge clk or negedge reset_n)
begin
  if (!reset_n)
  begin
    data_valid <= 0;
  end
  else
  begin
    data_valid <= start_gen;
  end
end

assign root = root_gen;

endmodule

