module radix2(
		input wire [1:0] state,
		input wire signed [23:0] din_a_r,
		input wire signed [23:0] din_a_i,
		input wire signed [23:0] din_b_r,
		input wire signed [23:0] din_b_i,
		input wire signed [23:0] w_r,
		input wire signed [23:0] w_i,
		output reg signed[23:0] op_r,
		output reg signed[23:0] op_i,
		output reg signed[23:0] delay_r,
		output reg signed[23:0] delay_i,
		output reg outvalid
	);
reg [41:0] a_r;
	reg [41:0] a_i;
	reg [41:0] b_r;
	reg [41:0] b_i;
	reg [41:0] w_r_r;
	reg [41:0] w_r_i;
	reg [41:0] w_i_r;
	reg [41:0] w_i_i;
	reg [41:0] w_r_r_r;
	reg [41:0] w_r_r_i;
	reg [41:0] w_r_i_r;
	reg [41:0] w_r_i_i;
	reg [41:0] w_i_r_r;
	reg [41:0] w_i_r_i;
	reg [41:0] w_i_i_r;
	reg [41:0] w_i_i_i;
	always @(*) begin
		case (state)
			2'b00: begin
				a_r <= din_a_r;
				a_i <= din_a_i;
				b_r <= din_b_r;
				b_i <= din_b_i;
				w_r_r <= w_r;
				w_r_i <= w_i;
				w_i_r <= w_r;
				w_i_i <= w_i;
			end
			2'b01: begin
				a_r <= a_r + b_r;
				a_i <= a_i + b_i;
				b_r <= a_r - b_r;
				b_i <= a_i - b_i;
			end
			2'b10: begin
				w_r_r_r <= w_r_r * w_r_r;
				w_r_r_i <= w_r_r * w_r_i;
				w_r_i_r <= w_r_i * w_r_r;
				w_r_i_i <= w_r_i * w_r_i;
				w_i_r_r <= w_i_r * w_i_r;
				w_i_r_i <= w_i_r * w_i_i;
				w_i_i_r <= w_i_i * w_i_r;
				w_i_i_i <= w_i_i * w_i_i;
				a_r <= (w_r_r_r - w_r_r_i) + (w_r_i_r - w_r_i_i);
				a_i <= (w_r_r_r + w_r_r_i) + (w_r_i_r + w_r_i_i);
				b_r <= (w_i_r_r - w_i_r_i) + (w_i_i_r - w_i_i_i);
				b_i <= (w_i_r_r + w_i_r_i) + (w_i_i_r + w_i_i_i);
			end
			default: begin
				a_r <= 0;
				a_i <= 0;
				b_r <= 0;
				b_i <= 0;
				w_r_r <= 0;
				w_r_i <= 0;
				w_i_r <= 0;
				w_i_i <= 0;
			end
		endcase
	end
	always @(*) begin
		case (state)
			2'b00: begin
				delay_r <= a_r;
				delay_i <= a_i;
				outvalid <= 0;
			end
			2'b01: begin
				delay_r <= a_r;
				delay_i <= a_i;
				outvalid <= 0;
			end
			2'b10: begin
				delay_r <= a_r;
				delay_i <= a_i;
				outvalid <= 1;
			end
			default: begin
				delay_r <= 0;
				delay_i <= 0;
				outvalid <= 0;
			end
		endcase
	end
	assign op_r = delay_r;
	assign op_i = delay_i;
endmodule

