                full <= 1'b1;
                empty <= 1'b0;
            end
        end
        if (read) begin
            index <= index - 1;
            if (index == 0) begin
                empty <= 1'b1;
                full  <= 1'b0;
            end
        end
    end
end

assign dout = mem[index];

