module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [1:0] state;

assign s_ready = state == 2'b00 ? 1'b1 : 1'b0;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        state <= 2'b00;
    end else begin
        if (s_valid) begin
            if (state == 2'b00) begin
                data_p1 <= s_data;
                state <= 2'b01;
            end
        end else begin
            if (state == 2'b01) begin
                data_p1 <= data_p2;
                state <= 2'b10;
            end
        end
        if (m_ready) begin
            if (state == 2'b10) begin
                data_p2 <= data_p1;
                state <= 2'b00;
            end
        end
    end
end

assign m_data = state == 2'b00 ? data_p1 : data_p2;
assign m_valid = state == 2'b00 ? 1'b1 : 1'b0;

endmodule

