module blake2_G(
                input wire [63 : 0]  a,
                input wire [63 : 0]  b,
                input wire [63 : 0]  c,
                input wire [63 : 0]  d,
                input wire [63 : 0]  m0,
                input wire [63 : 0]  m1,

                output wire [63 : 0] a_prim,
                output wire [63 : 0] b_prim,
                output wire [63 : 0] c_prim,
                output wire [63 : 0] d_prim
               );
reg [63 : 0] a0, a1, b0, b1, b2, b3, c0, c1, d0, d1, d2, d3;

    always @* begin
        a0 = a + m0;
        a1 = a0 ^ m1;
        b0 = a1 + b;
        b1 = b0 ^ c;
        b2 = b1 + c;
        b3 = b2 ^ d;
        c0 = b3 + d;
        c1 = c0 ^ m0;
        d0 = c1 + m1;
        d1 = d0 ^ m0;
        d2 = d1 + m1;
        d3 = d2 ^ m0;
    end

    assign a_prim = d3;
    assign b_prim = d2;
    assign c_prim = d1;
    assign d_prim = d0;

endmodule

