module minimal_modelb_rom_set (
    input            clk,
    input [17:0]     addr,
    output reg [7:0] data
);
reg [7:0] mem_0 [0:16383];
    reg [7:0] mem_1 [0:16383];
    reg [7:0] mem_2 [0:16383];

    initial begin
        $readmemh("minimal_modelb_rom_set_0.txt", mem_0);
        $readmemh("minimal_modelb_rom_set_1.txt", mem_1);
        $readmemh("minimal_modelb_rom_set_2.txt", mem_2);
    end

    always @ (posedge clk) begin
        case (addr[17:14])
