module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);
parameter CLK_FREQ = 100000000;
  parameter UART_BPS = 9600;
  parameter BPS_CNT = CLK_FREQ / UART_BPS;
  reg [31:0] clk_cnt = 0;
  reg [31:0] tx_cnt = 0;
  reg [7:0] tx_data = 0;
  reg tx_flag = 0;
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      tx_flag <= 0;
      tx_data <= 0;
      tx_cnt <= 0;
      clk_cnt <= 0;
    end else begin
      if (uart_en) begin
        tx_flag <= 1;
        tx_data <= uart_din;
        tx_cnt <= 0;
        clk_cnt <= 0;
      end
      if (tx_flag) begin
        if (tx_cnt == 0) begin
          clk_cnt <= clk_cnt + 1;
          if (clk_cnt == BPS_CNT) begin
            clk_cnt <= 0;
            tx_cnt <= tx_cnt + 1;
          end
        end
        if (tx_cnt == 8) begin
          tx_cnt <= 0;
          tx_flag <= 0;
        end
        if (tx_cnt == 9) begin
          uart_txd <= 1;
        end
        if (tx_cnt == 10) begin
          uart_txd <= tx_data[7];
          tx_data <= tx_data << 1;
          tx_cnt <= tx_cnt + 1;
        end
        if (tx_cnt == 11) begin
          uart_txd <= tx_data[6];
          tx_data <= tx_data << 1;
          tx_cnt <= tx_cnt + 1;
        end
        if (tx_cnt == 12) begin
          uart_txd <= tx_data[5];
          tx_data <= tx_data << 1;
          tx_cnt <= tx_cnt + 1;
        end
        if (tx_cnt == 13) begin
          uart_txd <= tx_data[4];
          tx_data <= tx_data << 1;
          tx_cnt <= tx_cnt + 1;
        end
        if (tx_cnt == 14) begin
          uart_txd <= tx_data[3];
          tx_data <= tx_data << 1;
          tx_cnt <= tx_cnt + 1;
        end
        if (tx_cnt == 15) begin
          uart_txd <= tx_data[2];
          tx_data <= tx_data << 1;
          tx_cnt <= tx_cnt + 1;
        end
        if (tx_cnt == 16) begin
          uart_txd <= tx_data[1];
          tx_data <= tx_data << 1;
          tx_cnt <= tx_cnt + 1;
        end
        if (tx_cnt == 17) begin
          uart_txd <= tx_data[0];
          tx_data <= tx_data << 1;
          tx_cnt <= tx_cnt + 1;
        end
        if (tx_cnt == 18) begin
          uart_txd <= 0;
          tx_cnt <= 0;
          tx_flag <= 0;
        end
      end
    end
  end
endmodule

