    case ({captnupdt, shiftnld})
        2'b10, 2'b11: begin
            updateclk <= clk;
            capture  <= 1'b1;
        end
        2'b01: begin
            updateclk <= clk;
            capture  <= 1'b0;
        end
        default: begin
            mainclk <= clk;
            update  <= 1'b1;
        end
    endcase
end

