        end else begin
            if (write) begin
                if (empty_n) begin
                    mem[index] <= din;
                    index <= index + 1;
                    if (index == DEPTH-1) begin
                        empty_n <= 1'b0;
                    end
                end
            end
            if (read) begin
                if (full_n) begin
                    index <= index - 1;
                    if (index == 0) begin
                        full_n <= 1'b0;
                    end
                end
            end
        end
    end
endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
); 

reg [31:0] timer;
reg pre;
  always @(posedge clk) begin
    if((timer == 32'd1000000)) begin
      if((btn_input == pre)) begin
        btn_output <= btn_input;
      end
      timer <= 32'd0;
      pre <= btn_input;
    end
    else begin
      timer <= timer + 1;
    end
  end
endmodule

