module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
reg [23:0] r_count;
reg [1:0] state;

assign o_ppfifo_clk = clk;
assign o_ppfifo_act = i_ppfifo_rdy;
assign o_ppfifo_stb = i_data_en & ~i_h_blank;
assign o_ppfifo_data = i_rgb;

always @(posedge clk) begin
  if (rst) begin
    r_count <= 0;
    state <= 2'b00;
  end else begin
    case (state)
      2'b00: begin
        if (i_ppfifo_rdy[0]) begin
          state <= 2'b01;
          r_count <= 0;
        end
      end
      2'b01: begin
        if (i_ppfifo_rdy[1]) begin
          state <= 2'b10;
          r_count <= 0;
        end
      end
      2'b10: begin
        if (i_ppfifo_rdy[0]) begin
          state <= 2'b00;
          r_count <= r_count + 1;
        end
        else if (i_ppfifo_rdy[1]) begin
          state <= 2'b01;
          r_count <= r_count + 1;
        end
        else if (r_count == i_ppfifo_size) begin
          state <= 2'b11;
        end
      end
      2'b11: begin
        state <= 2'b00;
      end
    endcase
  end
end

endmodule

