begin
	if (MR)
		counter <= 0;
	else if (counter == divider)
		counter <= 0;
	else
		counter <= counter + 1;
end
always @ (posedge Clock)
begin
	if (MR)
		Timeout <= 0;
	else if (counter == divider)
		Timeout <= 1;
end
endmodule

