      if((cnten == 1'b1)) begin
        if((cnt == 16'b1111111111111111)) begin
          cnt <= 16'b0000000000000000;
        end
        else begin
          cnt <= cnt + 16'b0000000000000001;
        end
      end
    end
  end
  assign q = cnt;
endmodule

