always @(posedge clk) begin
    if (train_valid) begin
        if (train_taken) begin
            if (counter == 3) begin
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end else begin
            if (counter == 0) begin
                counter <= 3;
            end else begin
                counter <= counter - 1;
            end
        end
    end else begin
        counter <= 2'b01;
    end
end

assign state = counter;

endmodule

