    reg z;
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
        end else begin
            case (state)
                2'b00: begin
                    if (w) begin
                        state <= 2'b01;
                    end else begin
                        state <= 2'b00;
                    end
                end
                2'b01: begin
                    if (w) begin
                        state <= 2'b10;
                    end else begin
                        state <= 2'b00;
                    end
                end
                2'b10: begin
                    if (w) begin
                        state <= 2'b11;
                    end else begin
                        state <= 2'b00;
                    end
                end
                2'b11: begin
                    if (w) begin
                        state <= 2'b10;
                    end else begin
                        state <= 2'b00;
                    end
                end
            endcase
        end
    end
    always @(posedge clk) begin
        case (state)
            2'b00: z <= 1'b0;
            2'b01: z <= 1'b0;
            2'b10: z <= 1'b1;
            2'b11: z <= 1'b0;
        endcase
    end
endmodule

module TopModule (
    clk,
    resetn,
    x,
    y,
    f,
    g
);

reg [1:0] state;
reg [1:0] next_state;

always @ (posedge clk or negedge resetn)
begin
    if (!resetn)
    begin
        state <= 2'b00;
    end
    else
    begin
        state <= next_state;
    end
end

always @ (state, x, y)
begin
    next_state = state;
    case (state)
        2'b00: begin
            next_state = 2'b01;
        end
        2'b01: begin
            if (x == 1)
            begin
                next_state = 2'b10;
            end
            else if (x == 0)
            begin
                next_state = 2'b01;
            end
            else if (x == 1)
            begin
                next_state = 2'b10;
            end
        end
        2'b10: begin
            if (x == 1)
            begin
                next_state = 2'b11;
            end
            else if (x == 0)
            begin
                next_state = 2'b10;
            end
            else if (x == 1)
            begin
                next_state = 2'b11;
            end
        end
        2'b11: begin
            if (y == 1)
            begin
                next_state = 2'b11;
            end
            else if (y == 0)
            begin
                next_state = 2'b10;
            end
            else if (y == 1)
            begin
                next_state = 2'b11;
            end
        end
        default: begin
            next_state = 2'b00;
        end
    endcase
end

assign f = state[0];
assign g = state[1];

endmodule

