module TopModule(
    clk,
    areset,
    bump_left,
    bump_right,
    ground,
    dig,
    walk_left,
    walk_right,
    aaah,
    digging
);
reg [1:0] state;
    reg falling;
    reg [1:0] next_state;
    reg [1:0] next_falling;
    always @(posedge clk) begin
        if (arst) begin
            state <= 2'b00;
            falling <= 0;
        end else begin
            state <= next_state;
            falling <= next_falling;
        end
    end
    always @(state, falling, ground, bump_left, bump_right) begin
        next_state <= state;
        next_falling <= falling;
        case (state)
            2'b00: begin
                if (ground) begin
                    if (bump_left) begin
                        next_state <= 2'b01;
                    end
                    else if (bump_right) begin
                        next_state <= 2'b10;
                    end
                    else begin
                        next_state <= 2'b00;
                    end
                end
                else if (falling) begin
                    next_state <= 2'b00;
                end
                else if (dig) begin
                    next_state <= 2'b00;
                end
            end
            2'b01: begin
                if (ground) begin
                    if (bump_left) begin
                        next_state <= 2'b00;
                    end
                    else if (bump_right) begin
                        next_state <= 2'b10;
                    end
                    else begin
                        next_state <= 2'b01;
                    end
                end
                else if (falling) begin
                    next_state <= 2'b01;
                end
                else if (dig) begin
                    next_state <= 2'b01;
                end
            end
            2'b10: begin
                if (ground) begin
                    if (bump_left) begin
                        next_state <= 2'b00;
                    end
                    else if (bump_right) begin
                        next_state <= 2'b10;
                    end
                    else begin
                        next_state <= 2'b10;
                    end
                end
                else if (falling) begin
                    next_state <= 2'b10;
                end
                else if (dig) begin
                    next_state <= 2'b10;
                end
            end
            default: begin
                next_state <= state;
            end
        endcase
        if (falling) begin
            next_falling <= 1;
        end
        else if (ground) begin
            next_falling <= 0;
        end
    end
    assign walk_left = (state == 2'b00) ? 1 : 0;
    assign walk_right = (state == 2'b01) ? 1 : 0;
    assign aaah = (state == 2'b00) ? 1 : 0;
    assign digging = (state == 2'b00) ? 1 : 0;
endmodule

